import binascii
size = 0x5FC
srcA = binascii.unhexlify("")
dstA = [0] * size
print(srcA)

src = 0
dst = 0
sPtr = 0

while dst < size:
    srcByte = srcA[src]
    copyLen1 = srcByte & 0b111
    sPtr = src + 1
    if (srcA[src] & 0b111) == 0:
        sPtr = src + 2
        copyLen1 = srcA[src + 1]
    dstZeros = srcByte >> 4
    if dstZeros == 0:
        dstZeros = srcA[sPtr]
        sPtr += 1
    copyLen1 -= 1
    while (copyLen1 != 0):
        dstA[dst] = srcA[sPtr]
        sPtr += 1
        dst += 1
        copyLen1 -= 1
    if srcByte & 0x08:
        src = sPtr + 1
        copyLen2 = dstZeros + 2
        sPtr = dst - srcA[sPtr]
        copyLen2 -= 1
        while copyLen2 >= 0:
            dstA[dst] = dstA[sPtr] # read from dstA cause we only have offsets here but sPtr = dst - *sPtr is a memory address in dst
            dst += 1
            sPtr += 1
            copyLen2 -= 1
    else:
        dstZeros -= 1
        src = sPtr
        while dstZeros >= 0:
            dstA[dst] = 0
            dst += 1
            dstZeros -= 1
            src = sPtr

print(bytes(dstA))
print(bytes(dstA).decode(encoding="ascii", errors="ignore"))
print(len(dstA))

with open("dstA.bin", mode="wb") as f:
    f.write(bytes(dstA))
